const CACHE="lacasetta-caisse",ASSETS=["./","./index.html","./style.css","./app.js","./manifest.json","./icon-192.png","./icon-512.png","./apple-touch-icon.png"];self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS))),self.skipWaiting()}),self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))}),self.addEventListener("fetch",e=>{const req=e.request;req.method==="GET"&&new URL(req.url).origin===self.location.origin&&e.respondWith(fetch(req,{cache:"no-store"}).then(res=>{const copy=res.clone();return caches.open(CACHE).then(cache=>cache.put(req,copy)),res}).catch(()=>caches.match(req).then(c=>c||caches.match("./index.html"))))});
